#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define PB push_back
#define sz(s) int((s).size())
#define bit(n,k) (((n)>>(k))&1)

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef unsigned int ui;

const int Lg=18, Tw=(1<<Lg), Max=Tw+10;

int arr[Max][Lg+3], temp[Lg+3], temp2[Lg+3], fact[Max], inv_fact[Max], Nbits, nVal, mod=1e9+7;

int mod_pow(int base, int exp){
    int res=1;
    while(exp){
        if(exp&1) res=1ll*res*base%mod;
        base=1ll*base*base%mod;
        exp>>=1;
    }
    return res;
}

void add_to(int *a,int *b){
    for(int i=0;i<=Nbits;i++)
        a[i]=(a[i]+b[i])%mod;
}

void subtract_from(int *a,int *b){
    for(int i=0;i<=Nbits;i++)
        a[i]=(a[i]-b[i])%mod;
}

void convolve_arrays(int *res,int *a,int *b){
    memset(temp,0,sizeof temp);
    for(int i=0;i<=Nbits;i++){
        for(int j=0;j<=i;j++){
            temp[i]=(temp[i]+1ll*a[j]*b[i-j])%mod;
        }
    }
    memcpy(res,temp,sizeof temp);
}

void forward_transform(int a[][Lg+3]){
    for(int i=0;i<Nbits;i++)
        for(int msk=nVal;msk>=0;msk--)
            if(bit(msk,i))
                add_to(a[msk],a[msk ^ (1<<i)]);
}

void inverse_transform(int a[][Lg+3]){
    for(int i=0;i<Nbits;i++)
        for(int msk=nVal;msk>=0;msk--)
            if(bit(msk,i))
                subtract_from(a[msk],a[msk ^ (1<<i)]);
}

vector<int> positions;

int main(){
    int K; cin>>nVal>>K>>mod;
    int total=mod_pow(K,nVal);
    if(nVal&1){ cout<<total<<endl; return 0; }
    Nbits=__builtin_popcount(nVal);
    int original_n=nVal;
    for(int i=0;i<Lg;i++){
        if(bit(nVal,i))
            positions.PB(i);
    }
    nVal=(1<<Nbits)-1;
    fact[0]=1;
    for(int i=1;i<Max;i++)
        fact[i]=1ll*i*fact[i-1]%mod;
    inv_fact[Max-1]=mod_pow(fact[Max-1],mod-2);
    for(int i=Max-2;i>=0;i--)
        inv_fact[i]=1ll*(i+1)*inv_fact[i+1]%mod;
    for(int i=0;i<=nVal;i++){
        int val=0;
        for(int j=0;j<Nbits;j++)
            val+=bit(i,j)*(1<<positions[j]);
        arr[i][__builtin_popcount(i)]=inv_fact[val];
    }
    forward_transform(arr);
    for(int i=0;i<=nVal;i++){
        int K_copy=K;
        memset(temp2,0,sizeof temp2); temp2[0]=1;
        while(K_copy){
            if(K_copy&1) convolve_arrays(temp2,temp2,arr[i]);
            convolve_arrays(arr[i],arr[i],arr[i]);
            K_copy>>=1;
        }
        memcpy(arr[i],temp2,sizeof temp2);
    }
    inverse_transform(arr);
    int answer=(total - 1ll*arr[nVal][Nbits]*fact[original_n])%mod;
    if(answer<0) answer+=mod;
    cout<<answer<<endl;
    return 0;
}
